// Full-state snapshots; no action replay and no offline simulation.
function dwPackSave(sim,view,speed,selected,accumulator,interaction={}){return {schema:2,savedAt:Date.now(),sim:{...sim,mods:[...sim.mods.values()],drones:sim.drones,droneById:undefined},view,speed,selected,accumulator,interaction}}
function dwUnpackSave(data){
 const fail=()=>{throw new Error('Invalid game save')},finite=value=>typeof value==='number'&&Number.isFinite(value),id=value=>Number.isSafeInteger(value)&&value>0;
 if(!data||![1,2].includes(data.schema)||!data.sim)fail();let legacy=data.schema===1,sim=data.sim;
 if(!Array.isArray(sim.mods)||!sim.mods.length||sim.mods.length>5000||!Array.isArray(sim.drones)||sim.drones.length>600||!Array.isArray(sim.edges)||!Array.isArray(sim.order)||!Array.isArray(sim.events))fail();
 for(let key of ['t','gridTime','active','fed','goal','wonAt','lastBlackoutMsg'])if(!finite(sim[key]))fail();if(!id(sim.nextId)||typeof sim.powered!=='boolean'||typeof sim.won!=='boolean')fail();
 let mods=new Map(),drones=new Map(),allIds=new Set();const resources=table=>{if(!table||typeof table!=='object')fail();for(let key of e)if(!finite(table[key])||table[key]<0)fail()};
 for(let mod of sim.mods){if(legacy){mod.hp=dwHull(mod.type);mod.cooldown=0;mod.charge=0;mod.lastShot=null}if(!id(mod.id)||allIds.has(mod.id)||!Object.hasOwn(n,mod.type)||!finite(mod.x)||!finite(mod.z)||Math.hypot(mod.x,mod.z)>70.01)fail();if(!finite(mod.hp)||mod.hp<0||mod.hp>dwHull(mod.type)||!finite(mod.cooldown)||mod.cooldown<0||mod.cooldown>120||!finite(mod.charge)||mod.charge<0||mod.charge>120)fail();if(mod.lastShot&&(!finite(mod.lastShot.x)||!finite(mod.lastShot.z)||!finite(mod.lastShot.at)))fail();allIds.add(mod.id);mods.set(mod.id,mod);for(let key of ['buildProg','prog','timer'])if(!finite(mod[key])||mod[key]<0)fail();for(let key of ['built','paused','working'])if(typeof mod[key]!=='boolean')fail();for(let key of ['inv','out','incoming','outgoing'])resources(mod[key]);if(!Array.isArray(mod.links)||!Array.isArray(mod.crew))fail();}
 if([...mods.values()].filter(mod=>mod.type==='core').length!==1)fail();
 for(let drone of sim.drones){if(!id(drone.id)||allIds.has(drone.id)||!u.includes(drone.role)||(drone.pending!==null&&!u.includes(drone.pending))||!mods.has(drone.node)||!finite(drone.x)||!finite(drone.z)||!finite(drone.think)||!Array.isArray(drone.path)||drone.path.some(node=>!mods.has(node))||(drone.carrying!==null&&!e.includes(drone.carrying)))fail();allIds.add(drone.id);drones.set(drone.id,drone);if(drone.task){let task=drone.task;if(task.kind==='haul'){if(!mods.has(task.from)||!mods.has(task.to)||!e.includes(task.res)||!['pickup','deliver'].includes(task.stage))fail()}else if(task.kind==='operate'){if(!mods.has(task.at)||!['going','working'].includes(task.stage))fail()}else fail()}}
 let edgeKeys=new Set();for(let edge of sim.edges){if(!Array.isArray(edge)||edge.length!==2||!mods.has(edge[0])||!mods.has(edge[1])||edge[0]===edge[1])fail();let key=[...edge].sort((a,b)=>a-b).join(':');if(edgeKeys.has(key))fail();edgeKeys.add(key)}
 for(let mod of mods.values()){if(new Set(mod.links).size!==mod.links.length||new Set(mod.crew).size!==mod.crew.length)fail();for(let link of mod.links){if(!mods.has(link)||!mods.get(link).links.includes(mod.id)||!edgeKeys.has([mod.id,link].sort((a,b)=>a-b).join(':')))fail()}for(let worker of mod.crew)if(!drones.has(worker)||drones.get(worker).task?.kind!=='operate'||drones.get(worker).task.at!==mod.id)fail()}
 for(let edge of sim.edges)if(!mods.get(edge[0]).links.includes(edge[1])||!mods.get(edge[1]).links.includes(edge[0]))fail();if(sim.order.some(node=>!mods.has(node)||mods.get(node).built)||sim.nextId<=Math.max(...allIds))fail();
 if(![0,1,2,4].includes(data.speed))fail();let view=data.view;if(!view||!Array.isArray(view.camera)||view.camera.length!==3||!view.camera.every(finite)||!Array.isArray(view.target)||view.target.length!==3||!view.target.every(finite)||!finite(view.zoom)||view.zoom<=0||!finite(view.polar))fail();if(!finite(data.accumulator)||data.accumulator<0||data.accumulator>=.05)fail();if(data.selected!==null&&!mods.has(data.selected))data.selected=null;
 if(legacy){sim.campaign=dwNewCampaign();if(sim.won){sim.campaign.phase='transition';sim.campaign.transitionLeft=.4;for(let mod of mods.values())if(mod.type==='model')mod.trained=true}}
 let campaign=sim.campaign;if(!campaign||!['training','transition','real','lost'].includes(campaign.phase)||!Number.isSafeInteger(campaign.wave)||campaign.wave<0||!Number.isSafeInteger(campaign.kills)||campaign.kills<0||!id(campaign.nextEnemy)||!Array.isArray(campaign.enemies)||campaign.enemies.length>32||typeof campaign.lossReason!=='string'||campaign.lossReason.length>200)fail();for(let key of ['transitionLeft','nextWave','extraction'])if(!finite(campaign[key])||campaign[key]<0)fail();if(campaign.transitionLeft>.4||campaign.nextWave>180||campaign.extraction>100)fail();if(campaign.phase!=='training'&&!sim.won)fail();let enemyIds=new Set();for(let enemy of campaign.enemies){if(!id(enemy.id)||enemyIds.has(enemy.id)||enemy.id>=campaign.nextEnemy||!['destroyer','distiller'].includes(enemy.type))fail();enemyIds.add(enemy.id);for(let key of ['x','z','hp','maxHp','revealedUntil','attackTimer'])if(!finite(enemy[key]))fail();if(Math.hypot(enemy.x,enemy.z)>130||enemy.hp<0||enemy.maxHp<=0||enemy.hp>enemy.maxHp||enemy.attackTimer<0||enemy.attackTimer>1.01)fail();if(enemy.target!==null&&!id(enemy.target))fail()}
 return {...data,schema:2,sim:{...sim,mods,droneById:drones}};
}
function dwLoadSave(){try{const raw=localStorage.getItem('datawars:save:v1');if(!raw)return null;if(raw.length>8000000)throw new Error('Save too large');return dwUnpackSave(JSON.parse(raw))}catch(error){dwSaveProblem='Your saved game could not be loaded. It has been kept.';return null}}
function dwMutationAllowed(){return dwWriter&&!dwLeaving&&!!window.__dataWarsStarted}
function dwSaveStatus(label){let status=document.getElementById('dw-save-status');if(status)status.textContent=label}
function dwWriteSave(){if(!dwWriter||dwLeaving||!dwStorageEnabled||dwSaveProblem||(!window.__dataWarsStarted&&!dwRestoredSave))return false;try{let view={camera:Jf.camera.position.toArray(),target:Jf.controls.target.toArray(),zoom:Jf.camera.zoom,polar:Jf.polar};let snapshot=dwPackSave(qf,view,Yf,Zf,Math.min(.049999,Math.max(0,ip)),{build:Xf,connector:dwConnectorMode,from:dwLinkFrom});localStorage.setItem('datawars:save:v1',JSON.stringify(snapshot));dwSaveStatus('Saved locally');return true}catch(error){dwStorageEnabled=false;dwSaveStatus('Saving unavailable');Qf.toast('Saving is unavailable in this browser. Existing saves were kept.','warn');return false}}
function dwApplySave(save){if(!save)return;for(let button of dwPauseButtons.values())button.remove();dwPauseButtons.clear();Jf.controls.dispose();Jf.renderer.dispose();Jf.renderer.domElement.remove();qf=save.sim;Jf=new zf(document.getElementById('app'),qf);np();Qf.setSim(qf);Jf.camera.position.fromArray(save.view.camera);Jf.controls.target.fromArray(save.view.target);Jf.camera.zoom=save.view.zoom;Jf.polar=save.view.polar;Jf.controls.minPolarAngle=Jf.controls.maxPolarAngle=Jf.polar;Jf.camera.updateProjectionMatrix();Jf.controls.update();Yf=save.speed;Qf.setSpeed(Yf);ip=save.accumulator;rp=performance.now();ep(null);Zf=save.selected;let interaction=save.interaction??{};if(interaction.build&&Object.hasOwn(n,interaction.build)&&n[interaction.build].buildable)ep(interaction.build);else if(interaction.connector&&(!interaction.from||qf.mods.has(interaction.from))){dwConnectorMode=true;dwLinkFrom=interaction.from??null;Qf.connectorBtn.classList.add('on');Qf.connectorBtn.setAttribute('aria-pressed','true')}dwRestoredSave=save;dwSaveStatus('Saved game restored');let play=document.getElementById('dw-play');if(play)play.textContent='Resume';Qf.timer=0}
function dwSetReadOnly(readonly){document.getElementById('hud').classList.toggle('dw-readonly',readonly);for(let button of document.querySelectorAll('#build button,#drones button,#speed button,#dw-new-game'))button.disabled=readonly;dwSaveStatus(readonly?'Game active in another tab':'Autosave ready')}
function dwAcquireWriter(){if(dwLockRequested||dwLeaving)return;dwLockRequested=true;dwSetReadOnly(true);if(!navigator.locks?.request){dwWriter=true;dwStorageEnabled=false;dwLockRequested=false;dwSetReadOnly(false);dwApplySave(dwRestoredSave);dwSaveStatus('Autosave unsupported');Qf.toast('You can play, but safe autosave is not supported by this browser.','warn');return}navigator.locks.request('datawars:writer:v1',async()=>{if(dwLeaving)return;let latest=dwLoadSave();dwWriter=true;dwSetReadOnly(false);dwApplySave(latest);if(dwSaveProblem){dwStorageEnabled=false;dwSaveStatus('Save could not be loaded');Qf.toast(dwSaveProblem,'warn')}else dwWriteSave();await new Promise(resolve=>{dwReleaseWriter=resolve});dwWriter=false;dwReleaseWriter=null}).catch(()=>{dwSaveStatus('Autosave unavailable');Qf.toast('Autosave could not acquire the game lock.','warn')}).finally(()=>{dwLockRequested=false;if(dwResumePending&&!dwLeaving){dwResumePending=false;dwAcquireWriter()}})}
function dwInitMemory(){document.getElementById('dw-new-game').onclick=()=>{if(!dwMutationAllowed())return;if(!window.confirm('Start a new colony? This replaces your saved game.'))return;dwSaveProblem='';dwStorageEnabled=true;$f()};dwAcquireWriter();setInterval(()=>dwWriteSave(),3000);window.addEventListener('datawars-started',()=>dwWriteSave());document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')dwWriteSave()});window.addEventListener('pagehide',()=>{dwWriteSave();dwLeaving=true;dwWriter=false;if(dwReleaseWriter)dwReleaseWriter()});window.addEventListener('pageshow',event=>{if(event.persisted){dwLeaving=false;if(dwLockRequested)dwResumePending=true;else dwAcquireWriter()}})}
